import '../css/sidebar.css';
import '../css/compact.css';
import './bootstrap';
import './pwa';
import './toast';
import './sidebar';
import './loading';
import './recovery-email';

import '../css/animations.css';

import Alpine from 'alpinejs';
import { Workbox } from 'workbox-window';

window.Alpine = Alpine;

// ── PWA: register the service worker (generated by vite-plugin-pwa) ──
if ('serviceWorker' in navigator) {
    window.addEventListener('load', function () {
        const wb = new Workbox('/sw.js');
        wb.register().catch(function (error) {
            console.log('Service Worker registration failed (run `npm run build` first):', error);
        });

        // Force an update check on every load so installed phones never keep
        // serving a stale precache (old bundles shipped broken hamburgers).
        navigator.serviceWorker.getRegistrations()
            .then(function (registrations) {
                registrations.forEach(function (reg) {
                    reg.update().catch(function () {});
                });
            })
            .catch(function () {});
    });
}

// ── PWA install prompt ──
// The browser's install event is kept for the single landing-page banner (pwa.js) and for
// any explicit "Install app" control marked [data-pwa-install] (e.g. in Settings).
window.deferredPrompt = null;

const syncInstallControls = () => {
    document.querySelectorAll('[data-pwa-install]').forEach((control) => {
        control.hidden = !window.deferredPrompt;
    });
};

window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    window.deferredPrompt = e;
    syncInstallControls();
});

document.addEventListener('click', (e) => {
    if (!e.target.closest('[data-pwa-install]') || !window.deferredPrompt) return;
    window.deferredPrompt.prompt();
    window.deferredPrompt.userChoice.finally(() => {
        window.deferredPrompt = null;
        syncInstallControls();
    });
});

window.addEventListener('appinstalled', () => {
    window.deferredPrompt = null;
    syncInstallControls();
    document.getElementById('installBanner')?.remove();
});

// ── Network status indicators ──
function setOfflineUI(offline) {
    document.body.classList.toggle('offline-mode', offline);
    const offlineBanner = document.getElementById('offlineBanner');
    if (offlineBanner) {
        // Sticky strip at the top of the page flow; never overlaps headers.
        if (offline && offlineBanner !== document.body.firstElementChild) document.body.prepend(offlineBanner);
        offlineBanner.hidden = !offline;
    }
}

window.addEventListener('online', () => setOfflineUI(false));
window.addEventListener('offline', () => setOfflineUI(true));
setOfflineUI(!navigator.onLine);

Alpine.start();
